export const FILES = {"/admin.html":{"type":"text/html; charset=utf-8","text":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <meta name=\"theme-color\" content=\"#0e2a4e\">\n  <title>إدارة تطبيق التعديل</title>\n  <link rel=\"icon\" href=\"/icon-192.png\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <script src=\"/admin.js\" defer></script>\n</head>\n<body class=\"admin-body\">\n  <header class=\"bar\">\n    <img src=\"/icon-192.png\" alt=\"\" width=\"32\" height=\"32\">\n    <div class=\"bar-text\"><strong>إدارة تطبيق التعديل</strong><span>للمسؤول فقط</span></div>\n    <button id=\"logout\" class=\"ghost\" hidden>خروج</button>\n  </header>\n\n  <main class=\"admin\">\n    <section id=\"login\" class=\"card login\">\n      <div class=\"lock\" aria-hidden=\"true\">🔒</div>\n      <h1>دخول المسؤول</h1>\n      <p class=\"small\">الصق مفتاح الإدارة المحفوظ في AWS Secrets Manager.</p>\n      <form id=\"login-form\" class=\"stack\">\n        <input id=\"key\" type=\"password\" autocomplete=\"off\" placeholder=\"مفتاح الإدارة\" dir=\"ltr\" required>\n        <button id=\"go\" type=\"submit\">دخول</button>\n      </form>\n    </section>\n\n    <div id=\"panel\" class=\"grid\" hidden>\n      <section class=\"card\">\n        <h2>إضافة شخص</h2>\n        <form id=\"add-form\" class=\"stack\">\n          <input id=\"name\" placeholder=\"الاسم، مثل: منى أحمد\" maxlength=\"60\" required>\n          <div class=\"roles\">\n            <label class=\"role\"><input type=\"radio\" name=\"role\" value=\"cabinet\" checked><span><strong>عضو بالحملة</strong><small>يرسل طلبات ويرى طلباته فقط</small></span></label>\n            <label class=\"role\"><input type=\"radio\" name=\"role\" value=\"client\"><span><strong>المرشح</strong><small>يرى كل الطلبات · واحد فقط</small></span></label>\n          </div>\n          <button id=\"add\" type=\"submit\">إضافة</button>\n        </form>\n        <div id=\"link\" class=\"link\" hidden></div>\n      </section>\n\n      <section class=\"card\">\n        <h2>الأشخاص <span id=\"count\" class=\"badge\"></span></h2>\n        <div id=\"people\" class=\"people\"></div>\n      </section>\n\n      <section class=\"card wide\">\n        <h2>سجل العمليات <button id=\"reload\" class=\"link-btn\" type=\"button\">تحديث</button></h2>\n        <ol id=\"audit\" class=\"audit\"></ol>\n      </section>\n    </div>\n  </main>\n  <div id=\"toast\" role=\"status\" hidden></div>\n</body>\n</html>\n"},"/admin.js":{"type":"text/javascript; charset=utf-8","text":"'use strict';\nconst $ = (s) => document.querySelector(s);\nconst ROLE = { client: 'المرشح', cabinet: 'عضو بالحملة' };\nconst EVENT = {\n  request: 'طلب جديد', agent_started: 'بدأ الوكيل', agent_start_failed: 'تعذّر بدء الوكيل', agent_refused: 'رفض الوكيل', agent_timeout: 'انتهى وقت الوكيل',\n  published: 'نُشر على الموقع', site_updated: 'تم تحديث الموقع', build_failed: 'فشل تحديث الموقع', refused_by_checks: 'رفضه الفحص', check_detail: 'تفاصيل الفحص',\n  publish_failed: 'فشل النشر', aborted: 'أُوقف', reverted: 'تم التراجع', revert_stale: 'تعذّر التراجع', revert_error: 'خطأ في التراجع',\n  joined: 'دخل من رابط', join_failed: 'رابط غير صالح', person_added: 'أُضيف شخص', invite_created: 'رابط دخول جديد', person_blocked: 'حُظر', person_unblocked: 'أُلغي الحظر',\n  admin_denied: 'مفتاح إدارة خاطئ', voice_error: 'خطأ في الصوت', file_skipped: 'ملف تم تجاهله', api_error: 'خطأ', advance_error: 'خطأ في المتابعة',\n};\nlet key = '';\ntry { key = sessionStorage.getItem('adminKey') || ''; } catch { /* private mode */ }\n\nfunction el(tag, attrs = {}, ...kids) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(attrs)) { if (k === 'class') e.className = v; else if (k === 'text') e.textContent = v; else if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else e.setAttribute(k, v); }\n  for (const k of kids) if (k) e.append(k);\n  return e;\n}\nfunction toast(m) { const t = $('#toast'); t.textContent = m; t.hidden = false; clearTimeout(toast.h); toast.h = setTimeout(() => { t.hidden = true; }, 3500); }\nasync function call(body) {\n  const r = await fetch('/api/admin', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Admin-Key': key }, body: JSON.stringify(body) });\n  let d = {}; try { d = await r.json(); } catch { /* */ }\n  if (r.status === 401) { showLogin(); toast(d.message || 'المفتاح غير صحيح.'); throw new Error('auth'); }\n  if (!d.ok) toast(d.message || 'حدث خطأ.');\n  return d;\n}\nconst when = (ts) => (ts ? new Date(ts * 1000).toLocaleString('ar-EG', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }) : 'لم يدخل بعد');\nfunction showLogin() { $('#panel').hidden = true; $('#login').hidden = false; $('#logout').hidden = true; }\n\nasync function load() {\n  const d = await call({ action: 'list' });\n  if (!d.ok) return;\n  $('#login').hidden = true; $('#panel').hidden = false; $('#logout').hidden = false;\n  const box = $('#people'); box.replaceChildren();\n  $('#count').textContent = d.people.filter((p) => p.active).length;\n  if (!d.people.length) box.append(el('p', { class: 'small', text: 'لا يوجد أحد بعد. أضف نفسك أولًا للتجربة.' }));\n  for (const p of d.people) {\n    box.append(el('div', { class: `person${p.active ? '' : ' off'}` },\n      el('div', { class: 'avatar', text: p.name.trim().charAt(0) }),\n      el('div', { class: 'info' },\n        el('strong', { text: p.name }),\n        el('span', { class: `tag ${p.role}`, text: ROLE[p.role] }),\n        p.active ? null : el('span', { class: 'tag blocked', text: 'محظور' }),\n        el('div', { class: 'small', text: `${p.devices} جهاز · ${p.alerts ? 'الإشعارات مفعلة' : 'بدون إشعارات'} · ${when(p.last_seen)}` })),\n      el('div', { class: 'btns' },\n        p.active ? el('button', { class: 'sm', text: 'رابط دخول', onclick: () => invite(p.id) }) : null,\n        p.active ? el('button', { class: 'sm bad', text: 'حظر', onclick: () => block(p) }) : el('button', { class: 'sm warn', text: 'إلغاء الحظر', onclick: () => unblock(p) }))));\n  }\n  await loadAudit();\n}\nasync function loadAudit() {\n  const a = await call({ action: 'audit', limit: 100 });\n  const list = $('#audit'); list.replaceChildren();\n  if (!a.rows?.length) list.append(el('li', { class: 'small', text: 'لا توجد عمليات بعد.' }));\n  for (const r of a.rows || []) {\n    const detail = r.detail && /^https:\\/\\/claude\\.ai\\//.test(r.detail)\n      ? el('a', { href: r.detail, target: '_blank', rel: 'noopener noreferrer', text: 'فتح تشغيل الوكيل' })\n      : r.detail ? el('span', { class: 'detail', text: r.detail.slice(0, 200) }) : null;\n    list.append(el('li', {},\n      el('span', { class: 'when', text: when(r.ts) }),\n      el('span', { class: 'ev', text: EVENT[r.event] || r.event }),\n      el('span', { class: 'actor', text: r.actor }),\n      r.change_id ? el('code', { text: r.change_id }) : null,\n      r.commit_sha ? el('code', { text: r.commit_sha.slice(0, 8) }) : null,\n      detail));\n  }\n}\nasync function invite(id) {\n  const d = await call({ action: 'invite', personId: id });\n  if (!d.ok) return;\n  const box = $('#link'); box.hidden = false;\n  const copy = el('button', { text: 'نسخ الرابط', onclick: async () => { try { await navigator.clipboard.writeText(d.link); toast('تم النسخ.'); } catch { toast('انسخه يدويًا.'); } } });\n  const share = navigator.share ? el('button', { class: 'warn', text: 'مشاركة', onclick: () => navigator.share({ text: `رابط دخولك لتطبيق تعديل الموقع (يعمل مرة واحدة):\\n${d.link}` }).catch(() => {}) }) : null;\n  box.replaceChildren(\n    el('strong', { text: `رابط دخول ${d.name}` }),\n    el('p', { class: 'small', text: 'يعمل مرة واحدة، على جهاز واحد، لمدة 7 أيام. أرسله له على واتساب.' }),\n    el('div', { class: 'link-box', text: d.link }),\n    el('div', { class: 'row' }, copy, share));\n  box.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n  load();\n}\nasync function block(p) { if (confirm(`حظر ${p.name}؟ سيخرج من كل أجهزته فورًا.`)) { await call({ action: 'block', personId: p.id }); load(); } }\nasync function unblock(p) { await call({ action: 'unblock', personId: p.id }); load(); }\n\n$('#login-form').addEventListener('submit', (e) => { e.preventDefault(); key = $('#key').value.trim(); try { sessionStorage.setItem('adminKey', key); } catch { /* */ } load().catch(() => {}); });\n$('#add-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const role = document.querySelector('input[name=role]:checked').value;\n  const d = await call({ action: 'add', name: $('#name').value, role });\n  if (d.ok) { $('#name').value = ''; toast('تمت الإضافة.'); await invite(d.personId); }\n});\n$('#reload').addEventListener('click', () => loadAudit().catch(() => {}));\n$('#logout').addEventListener('click', () => { key = ''; try { sessionStorage.removeItem('adminKey'); } catch { /* */ } $('#key').value = ''; showLogin(); });\nif (key) load().catch(() => {});\n"},"/app.js":{"type":"text/javascript; charset=utf-8","text":"// Chat app: type or say a text change, watch it go: agent editing -> checking & publishing -> site updating -> done.\n// All server text is shown with textContent (never as HTML).\n'use strict';\nconst $ = (s) => document.querySelector(s);\nconst state = { me: null, requests: [], timer: null, busy: false };\nconst STEPS = [['working', 'الوكيل يعدّل'], ['checking', 'فحص ونشر'], ['building', 'تحديث الموقع'], ['done', 'تم']];\n\nfunction el(tag, attrs = {}, ...kids) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(attrs)) {\n    if (k === 'class') e.className = v; else if (k === 'text') e.textContent = v; else if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else e.setAttribute(k, v);\n  }\n  for (const k of kids) if (k) e.append(k);\n  return e;\n}\nfunction toast(msg) {\n  const t = $('#toast'); t.textContent = msg; t.hidden = false;\n  clearTimeout(toast.h); toast.h = setTimeout(() => { t.hidden = true; }, 4000);\n}\nasync function api(path, body) {\n  const res = await fetch(path, body === undefined ? { credentials: 'same-origin' } : {\n    method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),\n  });\n  let data = {};\n  try { data = await res.json(); } catch { /* not json */ }\n  if (res.status === 401 && path !== '/api/join') { showLocked(); throw new Error('login'); }\n  return { status: res.status, ...data };\n}\nfunction showLocked(msg) {\n  stopPolling();\n  $('#app').hidden = true; $('#composer').hidden = true; $('#alerts').hidden = true;\n  if (msg) $('#locked-msg').textContent = msg;\n  $('#locked').hidden = false;\n}\nconst when = (ts) => new Date(ts * 1000).toLocaleString('ar-EG', { hour: 'numeric', minute: '2-digit', day: 'numeric', month: 'short' });\n\n// ---------- chat: each request = the person's bubble + the bot's live answer ----------\nconst BOT_TEXT = {\n  working: 'استلمت طلبك وأرسلته إلى الوكيل. جارٍ التعديل…',\n  checking: 'الوكيل انتهى. أفحص التعديل وأنشره…',\n  building: 'تم النشر. جارٍ تحديث الموقع…',\n  done: 'تم ✓ حدّث صفحة الموقع لترى التعديل.',\n  reverting: 'جارٍ إرجاع النص القديم…',\n};\nfunction steps(r) {\n  const order = STEPS.map((s) => s[0]);\n  const at = order.indexOf(r.status);\n  const ol = el('ol', { class: 'steps' });\n  STEPS.forEach(([, label], i) => ol.append(el('li', { class: i < at || r.status === 'done' ? 'past' : i === at ? 'now' : '', text: label })));\n  return ol;\n}\nfunction userBubble(r) {\n  return el('li', { class: `b ${r.mine ? 'me' : 'them'}` },\n    r.mine ? null : el('span', { class: 'who', text: r.from }),\n    document.createTextNode(r.text),\n    el('span', { class: 'meta', text: `${when(r.at)} · ${r.id}` }));\n}\nfunction botBubble(r) {\n  const li = el('li', { class: `b bot ${r.status}` });\n  li.append(el('div', { class: 'state' }, r.inProgress ? el('span', { class: 'spin', 'aria-hidden': 'true' }) : null,\n    document.createTextNode(BOT_TEXT[r.status] || r.statusText)));\n  if (['working', 'checking', 'building', 'done'].includes(r.status)) li.append(steps(r));\n  if (r.message) li.append(el('div', { class: 'msg', text: r.message }));\n  for (const e of r.edits) {\n    li.append(el('div', { class: 'edit' }, el('div', { class: 'page', text: e.page }),\n      el('div', { class: 'old' }, el('span', { class: 'lbl', text: 'القديم' }), el('span', { class: 'txt', text: e.old })),\n      el('div', { class: 'new' }, el('span', { class: 'lbl', text: 'الجديد' }), el('span', { class: 'txt', text: e.new }))));\n  }\n  const actions = el('div', { class: 'actions' });\n  if (r.status === 'done' && state.me.site) actions.append(el('a', { class: 'preview', href: state.me.site, target: '_blank', rel: 'noopener noreferrer', text: 'فتح الموقع' }));\n  if (r.can.abort) actions.append(el('button', { class: 'bad', text: 'إيقاف', onclick: () => act(r.id, 'abort', 'إيقاف هذا الطلب؟ لن يتغير شيء على الموقع.') }));\n  if (r.can.revert) actions.append(el('button', { class: 'warn', text: 'تراجع', onclick: () => act(r.id, 'revert', 'إرجاع النص القديم على الموقع؟') }));\n  if (actions.childElementCount) li.append(actions);\n  return li;\n}\nfunction render() {\n  const box = $('#app'), list = $('#list');\n  const nearBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 150;\n  list.replaceChildren(el('li', { class: 'b bot pre', text: `أهلًا ${state.me.name} 👋\\nاكتب أو سجّل بصوتك التعديل المطلوب على نصوص الموقع، مثلًا: «غيّر نص الفوتر في الصفحة الرئيسية إلى …».\\nأغيّر النصوص فقط، ويُنشر التعديل بعد الفحص مباشرة.` }));\n  for (const r of [...state.requests].reverse()) { list.append(userBubble(r)); list.append(botBubble(r)); }\n  if (nearBottom || state.jump) { box.scrollTop = box.scrollHeight; state.jump = false; }\n}\n\n// ---------- data ----------\nasync function refresh() {\n  const r = await api('/api/requests');\n  if (!r.ok) return;\n  state.requests = r.requests;\n  render();\n}\nfunction startPolling() {\n  stopPolling();\n  const tick = async () => {\n    try { await refresh(); } catch { /* offline: try again */ }\n    state.timer = setTimeout(tick, state.requests.some((r) => r.inProgress) ? 4000 : 20000);\n  };\n  state.timer = setTimeout(tick, 3000);\n}\nfunction stopPolling() { clearTimeout(state.timer); state.timer = null; }\n\nasync function act(id, action, question) {\n  if (state.busy || (question && !confirm(question))) return;\n  state.busy = true;\n  document.querySelectorAll('.b button').forEach((b) => { b.disabled = true; });\n  try { const r = await api(`/api/requests/${id}/${action}`, {}); toast(r.message || (r.ok ? 'تم.' : 'تعذّر التنفيذ.')); }\n  catch { toast('تعذّر الاتصال. حاول مرة أخرى.'); }\n  state.busy = false;\n  await refresh(); startPolling();\n}\nasync function send(ev) {\n  ev.preventDefault();\n  const box = $('#text'), text = box.value.trim();\n  if (!text || state.busy) return;\n  state.busy = true; $('#send').disabled = true; $('#send').textContent = 'جارٍ الإرسال…';\n  try {\n    const r = await api('/api/requests', { text });\n    if (r.ok) { box.value = ''; autosize(); state.jump = true; await refresh(); startPolling(); }\n    else toast(r.message || 'لم يُرسل الطلب.');\n  } catch (e) { if (e.message !== 'login') toast('تعذّر الاتصال. حاول مرة أخرى.'); }\n  state.busy = false; $('#send').disabled = false; $('#send').textContent = 'إرسال';\n}\nfunction autosize() { const t = $('#text'); t.style.height = 'auto'; t.style.height = Math.min(t.scrollHeight, 140) + 'px'; }\n\n// ---------- voice: record, turn into text, put it in the box to check before sending ----------\nconst rec = { media: null, chunks: [], timer: null, started: 0 };\nfunction pickType() {\n  for (const t of ['audio/webm;codecs=opus', 'audio/mp4', 'audio/webm', 'audio/ogg']) if (window.MediaRecorder && MediaRecorder.isTypeSupported(t)) return t;\n  return '';\n}\nasync function toggleMic() {\n  const mic = $('#mic');\n  if (mic.classList.contains('wait')) return;\n  if (rec.media) { rec.media.stop(); return; }\n  if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) { toast('التسجيل غير مدعوم على هذا المتصفح. اكتب طلبك.'); return; }\n  let stream;\n  try { stream = await navigator.mediaDevices.getUserMedia({ audio: true }); }\n  catch { toast('اسمح للتطبيق باستخدام الميكروفون ثم حاول مرة أخرى.'); return; }\n  const type = pickType();\n  rec.media = new MediaRecorder(stream, type ? { mimeType: type } : undefined);\n  rec.chunks = [];\n  rec.media.ondataavailable = (e) => { if (e.data.size) rec.chunks.push(e.data); };\n  rec.media.onstop = async () => {\n    stream.getTracks().forEach((t) => t.stop());\n    clearInterval(rec.timer); $('#rec').hidden = true; mic.classList.remove('on');\n    const blob = new Blob(rec.chunks, { type: (rec.media.mimeType || 'audio/webm').split(';')[0] });\n    rec.media = null;\n    if (Date.now() - rec.started < 800) { toast('التسجيل قصير جدًا.'); return; }\n    mic.classList.add('wait'); mic.textContent = '⏳';\n    try {\n      const res = await fetch('/api/voice', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': blob.type }, body: blob });\n      const d = await res.json().catch(() => ({}));\n      if (res.status === 401) return showLocked();\n      if (d.ok) {\n        const t = $('#text');\n        t.value = (t.value.trim() ? t.value.trim() + ' ' : '') + d.text;\n        autosize(); t.focus();\n        toast('راجع النص ثم اضغط إرسال.');\n      } else toast(d.message || 'تعذّر تحويل الصوت إلى نص.');\n    } catch { toast('تعذّر الاتصال. حاول مرة أخرى.'); }\n    mic.classList.remove('wait'); mic.textContent = '🎤';\n  };\n  rec.started = Date.now();\n  rec.media.start();\n  mic.classList.add('on'); $('#rec').hidden = false;\n  rec.timer = setInterval(() => {\n    const s = Math.floor((Date.now() - rec.started) / 1000);\n    $('#rec-time').textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;\n    if (s >= 60) rec.media?.stop();                    // one minute max\n  }, 250);\n}\n\n// ---------- phone alerts ----------\nconst isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);\nconst standalone = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;\nfunction keyBytes(b64) {\n  const s = atob(b64.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((b64.length + 3) % 4));\n  return Uint8Array.from(s, (c) => c.charCodeAt(0));\n}\nasync function setupAlerts() {\n  if (!('serviceWorker' in navigator)) return;\n  const reg = await navigator.serviceWorker.register('/sw.js');\n  if (isIOS && !standalone) {\n    const h = $('#hint'); h.hidden = false;\n    h.textContent = 'لتصلك الإشعارات على الآيفون: اضغط زر المشاركة ثم «إضافة إلى الشاشة الرئيسية»، وافتح التطبيق من الأيقونة.';\n    return;\n  }\n  if (!('PushManager' in window) || !state.me.vapidPublicKey) return;\n  const existing = await reg.pushManager.getSubscription();\n  if (existing && Notification.permission === 'granted') { await api('/api/push', { endpoint: existing.endpoint }); return; }\n  if (Notification.permission === 'denied') return;\n  const btn = $('#alerts'); btn.hidden = false;\n  btn.onclick = async () => {\n    try {\n      if ((await Notification.requestPermission()) !== 'granted') { toast('لم يتم السماح بالإشعارات.'); return; }\n      const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: keyBytes(state.me.vapidPublicKey) });\n      const r = await api('/api/push', { endpoint: sub.endpoint });\n      if (r.ok) { btn.hidden = true; toast('تم تفعيل الإشعارات.'); }\n    } catch { toast('تعذّر تفعيل الإشعارات على هذا الجهاز.'); }\n  };\n}\n\n// ---------- start ----------\nasync function start() {\n  if (location.hash.startsWith('#join=')) {\n    const token = location.hash.slice(6);\n    history.replaceState(null, '', '/');                // the link is one-time; remove it from the address bar\n    const r = await api('/api/join', { token });\n    if (!r.ok) return showLocked(r.message);\n  }\n  let me;\n  try { me = await api('/api/me'); } catch { return; }\n  if (!me.ok) return showLocked();\n  state.me = me;\n  $('#who').textContent = me.role === 'client' ? `${me.name} — كل الطلبات` : me.name;\n  $('#app').hidden = false; $('#composer').hidden = false;\n  $('#composer').addEventListener('submit', send);\n  $('#text').addEventListener('input', autosize);\n  $('#mic').addEventListener('click', toggleMic);\n  state.jump = true;\n  await refresh();\n  startPolling();\n  document.addEventListener('visibilitychange', () => { if (document.hidden) stopPolling(); else { refresh().catch(() => {}); startPolling(); } });\n  setupAlerts().catch(() => {});\n}\nstart();\n"},"/apple-touch-icon.png":{"type":"image/png","b64":""},"/icon-192.png":{"type":"image/png","b64":""},"/icon-512.png":{"type":"image/png","b64":""},"/index.html":{"type":"text/html; charset=utf-8","text":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#0e2a4e\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"apple-mobile-web-app-title\" content=\"تعديل الموقع\">\n  <title>تعديل نصوص الموقع</title>\n  <link rel=\"manifest\" href=\"/manifest.webmanifest\">\n  <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <script src=\"/app.js\" defer></script>\n</head>\n<body>\n  <header class=\"bar\">\n    <img src=\"/icon-192.png\" alt=\"\" width=\"32\" height=\"32\">\n    <div class=\"bar-text\"><strong>تعديل نصوص الموقع</strong><span id=\"who\"></span></div>\n    <button id=\"alerts\" class=\"ghost\" hidden>تفعيل الإشعارات</button>\n  </header>\n\n  <main id=\"locked\" class=\"screen\" hidden>\n    <div class=\"panel\">\n      <h1>تطبيق خاص</h1>\n      <p id=\"locked-msg\">هذا التطبيق بدعوة فقط. اطلب رابط الدخول من أحمد ثم افتحه على هاتفك.</p>\n    </div>\n  </main>\n\n  <main id=\"app\" class=\"screen\" hidden>\n    <div id=\"hint\" class=\"hint\" hidden></div>\n    <ol id=\"list\" class=\"chat\" aria-live=\"polite\"></ol>\n  </main>\n\n  <form id=\"composer\" hidden>\n    <button id=\"mic\" type=\"button\" class=\"mic\" aria-label=\"تسجيل صوتي\">🎤</button>\n    <textarea id=\"text\" rows=\"1\" maxlength=\"1500\" placeholder=\"اكتب أو سجّل طلبك…\" aria-label=\"طلبك\"></textarea>\n    <button id=\"send\" type=\"submit\" aria-label=\"إرسال\">إرسال</button>\n  </form>\n  <div id=\"rec\" class=\"rec\" hidden><span class=\"dot\"></span><span id=\"rec-time\">0:00</span> — جارٍ التسجيل… اضغط 🎤 للإيقاف</div>\n\n  <div id=\"toast\" role=\"status\" hidden></div>\n</body>\n</html>\n"},"/manifest.webmanifest":{"type":"application/manifest+json","text":"{\n  \"name\": \"تعديل نصوص الموقع\",\n  \"short_name\": \"تعديل الموقع\",\n  \"lang\": \"ar\",\n  \"dir\": \"rtl\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#f4f6f9\",\n  \"theme_color\": \"#0e2a4e\",\n  \"icons\": [\n    { \"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any maskable\" },\n    { \"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any maskable\" }\n  ]\n}\n"},"/style.css":{"type":"text/css; charset=utf-8","text":":root { --navy: #0e2a4e; --gold: #c9a227; --bg: #f4f6f9; --card: #fff; --ink: #1b2430; --muted: #66707d; --line: #dde2e8; --ok: #1f7a4d; --bad: #b3261e; }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; }\nbody { font-family: system-ui, -apple-system, \"Segoe UI\", Tahoma, \"Noto Sans Arabic\", sans-serif; background: var(--bg); color: var(--ink); font-size: 16px; line-height: 1.6; display: flex; flex-direction: column; }\nbutton { font: inherit; cursor: pointer; border-radius: 10px; border: 0; padding: 10px 16px; background: var(--navy); color: #fff; min-height: 44px; }\nbutton:disabled { opacity: .5; cursor: default; }\nbutton.ghost { background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.6); padding: 6px 10px; min-height: 36px; font-size: 14px; }\nbutton.ok { background: var(--ok); } button.bad { background: #fff; color: var(--bad); border: 1px solid var(--bad); } button.warn { background: #fff; color: var(--navy); border: 1px solid var(--navy); }\n.bar { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 10px; padding: 10px 14px; padding-top: max(10px, env(safe-area-inset-top)); background: var(--navy); color: #fff; }\n.bar img { border-radius: 8px; }\n.bar-text { flex: 1; display: flex; flex-direction: column; line-height: 1.3; }\n.bar-text span { font-size: 13px; opacity: .8; }\n.screen { flex: 1; overflow-y: auto; padding: 14px; }\n.panel { background: var(--card); border-radius: 14px; padding: 20px; max-width: 520px; margin: 40px auto; text-align: center; }\n.hint { background: #fff8e1; border: 1px solid #f0d78c; border-radius: 12px; padding: 10px 12px; font-size: 14px; margin-bottom: 10px; }\n.chat { list-style: none; margin: 0 auto; padding: 0 0 8px; max-width: 720px; display: flex; flex-direction: column; gap: 8px; }\n.b { max-width: 88%; padding: 10px 14px; border-radius: 16px; white-space: pre-wrap; overflow-wrap: anywhere; }\n.b.me { align-self: flex-start; background: var(--navy); color: #fff; border-end-start-radius: 4px; }\n.b.them { align-self: flex-start; background: #2c4a73; color: #fff; border-end-start-radius: 4px; }\n.b.bot { align-self: flex-end; background: var(--card); border: 1px solid var(--line); border-end-end-radius: 4px; white-space: normal; }\n.b .who { display: block; font-size: 12px; opacity: .75; margin-bottom: 2px; }\n.b .meta { display: block; font-size: 11px; opacity: .65; margin-top: 4px; }\n.b.bot.done { border-inline-start: 4px solid var(--ok); } .b.bot.refused, .b.bot.failed { border-inline-start: 4px solid var(--bad); }\n.b.bot.working, .b.bot.checking, .b.bot.building, .b.bot.reverting { border-inline-start: 4px solid var(--gold); }\n.b .state { font-weight: 600; display: flex; align-items: center; gap: 8px; }\n.b .msg { margin-top: 6px; padding: 8px 10px; border-radius: 8px; background: #fdecea; color: #7a2a24; font-size: 14px; }\n.b.bot.aborted .msg, .b.bot.reverted .msg { background: #eef2f7; color: var(--ink); }\n.steps { list-style: none; display: flex; gap: 4px; padding: 0; margin: 8px 0 0; font-size: 12px; }\n.steps li { flex: 1; text-align: center; padding: 4px 2px; border-radius: 6px; background: #eef2f7; color: var(--muted); }\n.steps li.past { background: #e3f4ea; color: var(--ok); } .steps li.now { background: #fff4d6; color: #8a6400; font-weight: 600; }\n.spin { width: 16px; height: 16px; border: 3px solid #e2c56b; border-top-color: transparent; border-radius: 50%; display: inline-block; animation: spin 1s linear infinite; }\n@keyframes spin { to { transform: rotate(360deg); } }\n@media (prefers-reduced-motion: reduce) { .spin { animation: none; } }\n.b .actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }\n.b .actions > * { flex: 1; min-width: 100px; text-align: center; }\n.b a.preview { display: inline-block; padding: 10px 16px; border-radius: 10px; border: 1px solid var(--navy); color: var(--navy); text-decoration: none; }\n#composer { position: sticky; bottom: 0; display: flex; gap: 8px; align-items: flex-end; padding: 10px 12px; padding-bottom: max(10px, env(safe-area-inset-bottom)); background: #fff; border-top: 1px solid var(--line); }\n#composer textarea { flex: 1; font: inherit; border: 1px solid var(--line); border-radius: 12px; padding: 10px 12px; resize: none; max-height: 140px; }\n.mic { background: #eef2f7; color: var(--ink); font-size: 20px; padding: 8px 12px; }\n.mic.on { background: var(--bad); color: #fff; }\n.mic.wait { opacity: .6; }\n.rec { position: fixed; inset-inline: 12px; bottom: 76px; margin: auto; max-width: 520px; background: #fff; border: 1px solid var(--bad); color: var(--bad); padding: 10px 14px; border-radius: 12px; text-align: center; z-index: 4; }\n.rec .dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; background: var(--bad); margin-inline-end: 6px; animation: blink 1s infinite; }\n@keyframes blink { 50% { opacity: .2; } }\n.edit { border-top: 1px dashed var(--line); padding-top: 8px; margin-top: 8px; }\n.edit .page { font-weight: 600; font-size: 14px; }\n.edit .old, .edit .new { padding: 6px 10px; border-radius: 8px; margin-top: 4px; white-space: pre-wrap; overflow-wrap: anywhere; }\n.edit .old { background: #fdecea; color: #7a2a24; } .edit .old .txt { text-decoration: line-through; }\n.edit .new { background: #e6f4ea; color: #14532d; }\n.edit .lbl { font-size: 12px; color: var(--muted); display: block; }\n.b.bot.pre { white-space: pre-wrap; }\n/* ---------- admin ---------- */\n.admin-body { overflow-y: auto; }\n.admin { width: 100%; max-width: 1100px; margin: 0 auto; padding: 20px 16px 40px; }\n.card { background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 18px; box-shadow: 0 1px 3px rgba(14,42,78,.06); }\n.card h2 { margin: 0 0 14px; font-size: 18px; display: flex; align-items: center; gap: 8px; }\n.login { max-width: 420px; margin: 8vh auto 0; text-align: center; padding: 28px 24px; }\n.login h1 { margin: 6px 0 4px; font-size: 22px; }\n.lock { font-size: 34px; }\n.stack { display: flex; flex-direction: column; gap: 10px; margin-top: 12px; }\n.admin input[type=text], .admin input[type=password], .admin input:not([type]) { width: 100%; font: inherit; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px; min-height: 48px; background: #fff; }\n.admin input:focus, #text:focus, textarea:focus { outline: 2px solid #9db4d6; outline-offset: 1px; border-color: #9db4d6; }\n.grid { display: grid; grid-template-columns: 1fr; gap: 16px; }\n@media (min-width: 900px) { .grid { grid-template-columns: 380px 1fr; align-items: start; } .grid .wide { grid-column: 1 / -1; } }\n.roles { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }\n.role { border: 1px solid var(--line); border-radius: 12px; padding: 10px; display: flex; gap: 8px; align-items: flex-start; cursor: pointer; }\n.role:has(input:checked) { border-color: var(--navy); background: #f1f5fb; }\n.role span { display: flex; flex-direction: column; } .role small { color: var(--muted); font-size: 12px; }\n.link { margin-top: 16px; padding: 14px; border-radius: 12px; background: #f1f7f3; border: 1px solid #cfe6d7; }\n.link-box { background: #fff; border: 1px dashed #9cc7ab; border-radius: 10px; padding: 10px; word-break: break-all; direction: ltr; text-align: left; font-size: 13px; margin: 8px 0; }\n.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; } .row > button { flex: 1; }\n.badge { background: #eef2f7; color: var(--muted); border-radius: 99px; padding: 0 10px; font-size: 13px; font-weight: 500; }\n.people { display: flex; flex-direction: column; }\n.person { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid var(--line); }\n.person:first-child { border-top: 0; }\n.person.off { opacity: .55; }\n.avatar { width: 40px; height: 40px; flex: none; border-radius: 50%; background: var(--navy); color: #fff; display: grid; place-items: center; font-weight: 700; }\n.person .info { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }\n.person .info .small { flex-basis: 100%; }\n.tag { font-size: 12px; padding: 1px 8px; border-radius: 99px; background: #eef2f7; }\n.tag.client { background: #fff4d6; color: #8a6400; } .tag.blocked { background: #fdecea; color: var(--bad); }\n.btns { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }\nbutton.sm { min-height: 36px; padding: 6px 12px; font-size: 14px; }\n.link-btn { background: none; color: var(--navy); padding: 0 6px; min-height: auto; font-size: 14px; text-decoration: underline; margin-inline-start: auto; }\n.audit { list-style: none; margin: 0; padding: 0; max-height: 460px; overflow-y: auto; }\n.audit li { display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: baseline; padding: 8px 0; border-top: 1px solid var(--line); font-size: 14px; }\n.audit li:first-child { border-top: 0; }\n.audit .when { color: var(--muted); font-size: 12px; min-width: 110px; }\n.audit .ev { font-weight: 600; } .audit .actor { color: var(--muted); }\n.audit code { background: #eef2f7; padding: 0 6px; border-radius: 6px; font-size: 12px; direction: ltr; }\n.audit .detail { flex-basis: 100%; color: var(--muted); font-size: 13px; overflow-wrap: anywhere; }\n.small { font-size: 13px; color: var(--muted); }\n.grow { flex: 1; } .mt { margin-top: 8px; } .plain { list-style: none; padding: 0; margin: 0; }\n/* wide screens: keep the chat app centered and readable */\n@media (min-width: 760px) { #composer { max-width: 760px; margin: 0 auto; width: 100%; border-inline: 1px solid var(--line); border-radius: 16px 16px 0 0; } }\n[hidden] { display: none !important; }\n@media (max-width: 600px) {\n  .person { flex-wrap: wrap; }\n  .person .info { flex-basis: calc(100% - 52px); }\n  .btns { width: 100%; justify-content: stretch; } .btns button { flex: 1; }\n  .roles { grid-template-columns: 1fr; }\n}\n"},"/sw.js":{"type":"text/javascript; charset=utf-8","text":"// Shows a phone alert. The alert has NO message content on purpose: the text stays inside the app.\nself.addEventListener('install', () => self.skipWaiting());\nself.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));\nself.addEventListener('push', (e) => {\n  e.waitUntil(self.registration.showNotification('تعديل نصوص الموقع', {\n    body: 'لديك رسالة جديدة. افتح التطبيق.', icon: '/icon-192.png', badge: '/icon-192.png', tag: 'new', renotify: true, lang: 'ar', dir: 'rtl',\n  }));\n});\nself.addEventListener('notificationclick', (e) => {\n  e.notification.close();\n  e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {\n    for (const c of list) if ('focus' in c) return c.focus();\n    return self.clients.openWindow('/');\n  }));\n});\n"}};
export const HEADERS_FILE = "/*\n  Content-Security-Policy: default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; connect-src 'self'; manifest-src 'self'; worker-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: no-referrer\n  X-Robots-Tag: noindex, nofollow\n  Permissions-Policy: camera=(), microphone=(self), geolocation=()\n/sw.js\n  Cache-Control: no-cache\n/app.js\n  Cache-Control: no-cache\n/admin.js\n  Cache-Control: no-cache\n";
